settings.custom_css:
/* =========================================================
   RAMIS — PREMIUM FAQ HERO
   Scoped to: Root Container 1cf4109
========================================================= */

selector {
    /* =====================================================
       DESIGN TOKENS
    ===================================================== */
    --ramis-primary: #006660;
    --ramis-dark: #003F3C;
    --ramis-secondary: #004F4B;
    --ramis-gold: #FFCE3A;
    --ramis-white: #FFFFFF;

    position: relative;
    isolation: isolate;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 88% 15%,
            rgba(255, 206, 58, 0.11),
            transparent 29%
        ),
        radial-gradient(
            circle at 8% 85%,
            rgba(0, 180, 165, 0.15),
            transparent 34%
        ),
        linear-gradient(
            135deg,
            var(--ramis-dark) 0%,
            var(--ramis-primary) 52%,
            #00332F 100%
        );

    border-radius: 0 0 30px 30px;

    box-shadow:
        0 18px 45px rgba(0, 63, 60, 0.16);

    z-index: 1;
}


/* =========================================================
   ATMOSPHERIC BACKGROUND LIGHT
========================================================= */

selector::before {
    content: "";
    position: absolute;

    width: 320px;
    height: 320px;

    top: -170px;
    right: 9%;

    background: rgba(255, 206, 58, 0.07);
    border-radius: 50%;

    filter: blur(70px);

    pointer-events: none;
    z-index: -1;
}


selector::after {
    content: "";
    position: absolute;

    width: 360px;
    height: 360px;

    bottom: -220px;
    left: 4%;

    background: rgba(0, 180, 165, 0.08);
    border-radius: 50%;

    filter: blur(85px);

    pointer-events: none;
    z-index: -1;
}


/* =========================================================
   CONTENT LAYER
========================================================= */

selector .elementor-element-a03db9a,
selector .elementor-element-7eefd28 {
    position: relative;
    z-index: 2;
}


/* =========================================================
   TEXT CONTAINER
========================================================= */

selector .elementor-element-a03db9a {
    position: relative;
}


/* =========================================================
   HERO TITLE
========================================================= */

selector .elementor-element-b9db7ee {
    position: relative;
    z-index: 2;
}

selector .elementor-element-b9db7ee p {
    margin: 0;

    color: var(--ramis-white) !important;

    font-size: clamp(32px, 4vw, 46px);
    font-weight: 900;
    line-height: 1.4;

    letter-spacing: -0.4px;

    text-shadow:
        0 4px 18px rgba(0, 0, 0, 0.18);
}


/* =========================================================
   GOLD ACCENT LINE
========================================================= */

selector .elementor-element-b9db7ee::after {
    content: "";

    display: block;

    width: 55px;
    height: 4px;

    margin-top: 14px;

    background: var(--ramis-gold);
    border-radius: 20px;

    box-shadow:
        0 0 14px rgba(255, 206, 58, 0.18);

    transition:
        width 0.4s cubic-bezier(.2,.8,.2,1),
        box-shadow 0.4s ease;
}


/* =========================================================
   TITLE INTERACTION
========================================================= */

selector .elementor-element-b9db7ee:hover::after {
    width: 82px;

    box-shadow:
        0 0 18px rgba(255, 206, 58, 0.28);
}


/* =========================================================
   HERO DESCRIPTION
========================================================= */

selector .elementor-element-b4064e8 {
    position: relative;
    z-index: 2;

    transition:
        opacity 0.35s ease,
        transform 0.35s ease;
}

selector .elementor-element-b4064e8 p {
    margin: 0;

    max-width: 590px;

    color: rgba(255, 255, 255, 0.74) !important;

    font-size: 15px;
    font-weight: 400;

    line-height: 2.15;

    text-shadow:
        0 2px 10px rgba(0, 0, 0, 0.08);
}

selector .elementor-element-a03db9a:hover
.elementor-element-b4064e8 {
    opacity: 0.92;
}


/* =========================================================
   IMAGE CONTAINER
========================================================= */

selector .elementor-element-7eefd28 {
    position: relative;

    transform: rotate(2deg);

    transition:
        transform 0.45s cubic-bezier(.2,.8,.2,1);
}


/* =========================================================
   PREMIUM IMAGE FRAME
========================================================= */

selector .elementor-element-7eefd28::before {
    content: "";

    position: absolute;

    inset: -9px;

    border: 1px solid rgba(255, 206, 58, 0.25);

    border-radius: 25px;

    background:
        linear-gradient(
            135deg,
            rgba(255, 206, 58, 0.06),
            transparent 42%,
            rgba(255, 255, 255, 0.025)
        );

    pointer-events: none;

    z-index: -1;

    transition:
        border-color 0.4s ease,
        box-shadow 0.4s ease;
}


/* =========================================================
   IMAGE WIDGET
========================================================= */

selector .elementor-element-89631d1 {
    position: relative;

    overflow: hidden;

    border-radius: 20px;

    border: 1px solid rgba(255, 255, 255, 0.15);

    box-shadow:
        0 25px 55px rgba(0, 0, 0, 0.28);

    background: rgba(255, 255, 255, 0.04);

    transition:
        transform 0.45s cubic-bezier(.2,.8,.2,1),
        box-shadow 0.45s ease,
        border-color 0.4s ease;
}


/* =========================================================
   IMAGE
========================================================= */

selector .elementor-element-89631d1 img {
    display: block;

    width: 100%;
    height: auto;

    border-radius: 19px;

    transition:
        transform 0.55s cubic-bezier(.2,.8,.2,1),
        filter 0.4s ease;
}


/* =========================================================
   IMAGE HOVER
========================================================= */

selector .elementor-element-7eefd28:hover {
    transform:
        rotate(0deg)
        translateY(-7px);
}

selector .elementor-element-7eefd28:hover::before {
    border-color: rgba(255, 206, 58, 0.38);

    box-shadow:
        0 0 28px rgba(255, 206, 58, 0.08);
}

selector .elementor-element-89631d1:hover {
    border-color: rgba(255, 206, 58, 0.26);

    box-shadow:
        0 30px 65px rgba(0, 0, 0, 0.34),
        0 0 24px rgba(255, 206, 58, 0.06);
}

selector .elementor-element-89631d1:hover img {
    transform: scale(1.025);
}


/* =========================================================
   TABLET — 768px TO 1024px
========================================================= */

@media (min-width: 768px) and (max-width: 1024px) {

    selector {
        border-radius: 0 0 26px 26px;
    }

    selector .elementor-element-b9db7ee p {
        font-size: clamp(30px, 5vw, 40px);
    }

    selector .elementor-element-b4064e8 p {
        max-width: 500px;
        font-size: 15px;
        line-height: 2.05;
    }

    selector .elementor-element-7eefd28 {
        transform: rotate(1.2deg);
    }

    selector .elementor-element-7eefd28::before {
        inset: -7px;
    }
}


/* =========================================================
   MOBILE — BELOW 767px
========================================================= */

@media (max-width: 767px) {

    selector {
        border-radius: 0 0 22px 22px;

        box-shadow:
            0 12px 30px rgba(0, 63, 60, 0.14);
    }

    selector::before {
        width: 220px;
        height: 220px;

        top: -120px;
        right: -70px;

        filter: blur(60px);
    }

    selector::after {
        width: 240px;
        height: 240px;

        bottom: -150px;
        left: -80px;

        filter: blur(65px);
    }


    /* ---------------------------------------------
       MOBILE TEXT
    --------------------------------------------- */

    selector .elementor-element-a03db9a {
        text-align: center;
    }

    selector .elementor-element-b9db7ee p {
        font-size: clamp(29px, 8.5vw, 36px);
        line-height: 1.45;

        letter-spacing: 0;

        text-shadow:
            0 3px 14px rgba(0, 0, 0, 0.16);
    }

    selector .elementor-element-b9db7ee::after {
        width: 52px;

        margin-top: 12px;
        margin-left: auto;
        margin-right: auto;
    }

    selector .elementor-element-b4064e8 {
        margin-top: 4px;
    }

    selector .elementor-element-b4064e8 p {
        max-width: 100%;

        font-size: 14px;
        line-height: 2.05;

        color: rgba(255, 255, 255, 0.72) !important;
    }


    /* ---------------------------------------------
       MOBILE IMAGE
    --------------------------------------------- */

    selector .elementor-element-7eefd28 {
        transform: none;
    }

    selector .elementor-element-7eefd28::before {
        inset: -5px;

        border-radius: 22px;
    }

    selector .elementor-element-89631d1 {
        border-radius: 18px;

        box-shadow:
            0 20px 40px rgba(0, 0, 0, 0.24);
    }

    selector .elementor-element-89631d1 img {
        border-radius: 17px;
    }

    selector .elementor-element-7eefd28:hover {
        transform: translateY(-4px);
    }

    selector .elementor-element-89631d1:hover img {
        transform: scale(1.015);
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    selector *,
    selector *::before,
    selector *::after {
        transition: none !important;
        animation: none !important;
    }

    selector .elementor-element-7eefd28,
    selector .elementor-element-7eefd28:hover {
        transform: none !important;
    }

    selector .elementor-element-89631d1 img,
    selector .elementor-element-89631d1:hover img {
        transform: none !important;
    }
}

/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}
